import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-03-30","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-03-30","date":"2021-03-30T00:00:00.000Z","updated":"2021-03-31T00:00:00.000Z","tags":["Ceph","Orchestrator","Storage","Distributed Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-03-30.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-03-30.md","lastUpdated":1780459816000}'),l={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-03-30.md"};function i(s,e,h,c,d,n){return t(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph Orchestrator会议主要讨论了Ceph存储系统的关键议题，包括网络配置、虚拟IP服务、NFS服务的配置和管理，以及Ceph Dashboard的发展路线图。会议还涉及了Ceph与Rook集成的具体问题，以及如何优化NFS和RGW服务的部署和管理。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>网络配置与管理</strong></p><ul><li>讨论了如何通过修改网络列表来确保子网配置的正确性，并探讨了<code>list networks</code>命令与<code>gather facts</code>命令的功能重叠问题。</li><li>决定将这两个功能合并，以简化管理和避免重复。</li></ul></li><li><p><strong>虚拟IP服务（VIP）</strong></p><ul><li>讨论了VIP服务在NFS服务中的应用，特别是在NFS守护进程重启或迁移时的IP地址管理问题。</li><li>提出了通过扩展放置规范（placement spec）来简化VIP服务的配置和管理。</li></ul></li><li><p><strong>NFS服务配置</strong></p><ul><li>讨论了NFS服务的配置问题，特别是RGW块在NFS配置中的必要性和如何与Rook集成。</li><li>决定将RGW配置提升到orchestrator层，以便于统一管理和避免在Rook和Cephadm中的重复配置。</li></ul></li><li><p><strong>Ceph Dashboard发展</strong></p><ul><li>讨论了Ceph Dashboard的发展路线图，特别是在即将到来的CDS会议中的讨论安排。</li><li>强调了Dashboard与Orchestrator以及其他组件的同步和集成需求。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>合并<code>list networks</code>和<code>gather facts</code>命令的功能。</li><li>扩展VIP服务的放置规范，以简化其配置和管理。</li><li>将RGW配置提升到orchestrator层，以统一管理和避免重复。</li><li>在即将到来的CDS会议中安排关于Ceph Dashboard的讨论。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>实施<code>list networks</code>和<code>gather facts</code>命令的合并。</li><li>开发和测试VIP服务的扩展放置规范。</li><li>在orchestrator层实现RGW配置的管理。</li><li>准备在CDS会议中关于Ceph Dashboard的讨论材料。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li>讨论了NVMF（NVMe over Fabrics）的管理层和子系统与命名空间模型的选择。</li><li>讨论了Ceph与Rook在NFS服务配置上的差异和集成问题。</li></ul><p>本次会议为Ceph存储系统的未来发展方向和具体实施细节提供了明确的指导和决策。</p>',12)])])}const _=a(l,[["render",i]]);export{u as __pageData,_ as default};
